defense.vulnerable_config:
# Find GPOs with non-admin write permissions:
Get-NetGPO | ForEach-Object {
  $gpo = $_
  Get-ObjectAcl $gpo.AdsPath -ResolveGUIDs | Where-Object {
    $_.ActiveDirectoryRights -match 'Write|Create|GenericAll' -and
    $_.IdentityReference -notmatch 'Domain Admins|CREATOR OWNER|SYSTEM|Enterprise Admins'
  } | Select-Object @{N='GPO';E={$gpo.DisplayName}},IdentityReference,ActiveDirectoryRights
}
# Output: 'IT_Computers_GPO' - CORP\HelpDesk - WriteProperty → VULNERABLE
